[Expected Approach] Using Morris Traversal Algorithm - O(n) Time and O(1) SpaceThe idea is to use Morris Traversal Algorithm to perform pre-order traversal of the binary tree, while maintaining the count of nodes visited so far.Below is the implementation of the above approach:
            C++

    // C++ program for  nth node of
// preorder traversals
#include <bits/stdc++.h>
using namespace std;

class Node {
public:
    int data;
    Node* left, *right;
    Node (int x) {
        data = x;
        left = nullptr;
        right = nullptr;
    }
};

// Given a binary tree, print its nth
// preorder node.
int nthPreorder(Node* root, int n) {

    Node* curr = root;
    while (curr != nullptr) {

        // if left child is null, check 
        // curr node and move to right node.
        if (curr->left == nullptr) {

            if (n==1) return curr->data;
            n--;
            curr = curr->right;
        }
        else {

            // Find the inorder predecessor of curr
            Node* pre = curr->left;
            while (pre->right != nullptr
                   && pre->right != curr)
                pre = pre->right;

            // Make curr as the right child of its
            // inorder predecessor, check curr node 
            // and move to left node.
            if (pre->right == nullptr) {
                pre->right = curr;

                if (n == 1) return curr->data;
                n--;

                curr = curr->left;
            }

            // Revert the changes made in the 'if' part to
            // restore the original tree i.e., fix the right
            // child of predecessor.
            else {
                pre->right = nullptr;
                curr = curr->right;
            }
        }
    }

    // If number of nodes is
  	// less than n.
    return -1;
}

int main() {

    // hard coded binary tree.
    //       10
    //     /   \
    //   20     30
    //  /   \
    // 40     50
    Node* root = new Node(10);
    root->left = new Node(20);
    root->right = new Node(30);
    root->left->left = new Node(40);
    root->left->right = new Node(50);

    int n = 4;

    cout << nthPreorder(root, n) << endl;
    return 0;
}


